/** static u16 DetermineEggSpeciesAndParentSlots(struct DayCare *daycare, u8 *parentSlots) */
export function DetermineEggSpeciesAndParentSlots(daycare: any, parentSlots: any): any {
  let i: any = null;
      const species: any[] = [];
      let eggSpecies: any = null;

      for (i = 0; i < DAYCARE_MON_COUNT; i++)
      {
          species[i] = GetBoxMonData(daycare.mons[i].mon, MON_DATA_SPECIES);
          if (species[i] == SPECIES_DITTO)
          {
              parentSlots[0] = i ^ 1;
              parentSlots[1] = i;
          }
          else if (GetBoxMonGender(daycare.mons[i].mon) == MON_FEMALE)
          {
              parentSlots[0] = i;
              parentSlots[1] = i ^ 1;
          }
      }

      eggSpecies = GetEggSpecies(species[parentSlots[0]]);
      if (eggSpecies == SPECIES_NIDORAN_F && daycare.offspringPersonality & EGG_GENDER_MALE)
      {
          eggSpecies = SPECIES_NIDORAN_M;
      }
      if (eggSpecies == SPECIES_ILLUMISE && daycare.offspringPersonality & EGG_GENDER_MALE)
      {
          eggSpecies = SPECIES_VOLBEAT;
      }

       
      if (species[parentSlots[1]] == SPECIES_DITTO && GetBoxMonGender(daycare.mons[parentSlots[0]].mon) != MON_FEMALE)
      {
          let ditto: any = parentSlots[1];
          parentSlots[1] = parentSlots[0];
          parentSlots[0] = ditto;
      }

      return eggSpecies;
}

/** static void _GiveEggFromDaycare(struct DayCare *daycare) */
export function _GiveEggFromDaycare(daycare: any): any {
  let egg: any = null;
      let species: any = null;
      const parentSlots: any[] = [];
      let isEgg: any = null;

      species = DetermineEggSpeciesAndParentSlots(daycare, parentSlots);
      AlterEggSpeciesWithIncenseItem(species, daycare);
      SetInitialEggData(egg, species, daycare);
      InheritIVs(egg, daycare);
      BuildEggMoveset(egg,daycare.mons[parentSlots[1]].mon,daycare.mons[parentSlots[0]].mon);

      if (species == SPECIES_PICHU)
          GiveVoltTackleIfLightBall(egg, daycare);

      isEgg = TRUE;
      SetMonData(egg, MON_DATA_IS_EGG,isEgg);
      gPlayerParty[PARTY_SIZE - 1] = egg;
      CompactPartySlots();
      CalculatePlayerPartyCount();
      RemoveEggFromDayCare(daycare);
}

/** void CreateEgg(struct Pokemon *mon, u16 species, bool8 setHotSpringsLocation) */
