      metLevel = 0;
      ball = ITEM_POKE_BALL;
      language = LANGUAGE_JAPANESE;
      SetMonData(mon, MON_DATA_POKEBALL,ball);
      SetMonData(mon, MON_DATA_NICKNAME, sJapaneseEggNickname);
