/** static bool8 TryProduceOrHatchEgg(struct DayCare *daycare) */
export function TryProduceOrHatchEgg(daycare: any): any {
  let i, validEggs = 0;

      for (i = 0; i < DAYCARE_MON_COUNT; i++)
      {
          if (GetBoxMonData(daycare.mons[i].mon, MON_DATA_SANITY_HAS_SPECIES))
              daycare.mons[i].steps++, validEggs++;
      }

       
      if (daycare.offspringPersonality == 0 && validEggs == DAYCARE_MON_COUNT && (daycare.mons[1].steps & 0xFF) == 0xFF)
      {
          let compatibility: any = GetDaycareCompatibilityScore(daycare);
          if (compatibility > (Random() * 100) / USHRT_MAX)
              TriggerPendingDaycareEgg();
      }

       
      if (++daycare.stepCounter == 255)
      {
          let eggCycles: any = null;
          let toSub: any = GetEggCyclesToSubtract();

          for (i = 0; i < gPlayerPartyCount; i++)
          {
              if (!GetMonData(gPlayerParty[i], MON_DATA_IS_EGG))
                  continue;
              if (GetMonData(gPlayerParty[i], MON_DATA_SANITY_IS_BAD_EGG))
                  continue;

              eggCycles = GetMonData(gPlayerParty[i], MON_DATA_FRIENDSHIP);
              if (eggCycles != 0)
              {
                  if (eggCycles >= toSub)
                      eggCycles -= toSub;
                  else
                      eggCycles -= 1;

                  SetMonData(gPlayerParty[i], MON_DATA_FRIENDSHIP,eggCycles);
              }
              else
              {
                  gSpecialVar_0x8004 = i;
                  return TRUE;
              }
          }
      }

      return FALSE;
}

