/** static void Task_HandleDaycareLevelMenuInput(u8 taskId) */
export function Task_HandleDaycareLevelMenuInput(taskId: any): any {
  let input: any = ListMenu_ProcessInput(gTasks[taskId].tMenuListTaskId);

      if (JOY_NEW(A_BUTTON))
      {
          switch (input)
          {
          case 0:
          case 1:
              gSpecialVar_Result = input;
              break;
          case DAYCARE_LEVEL_MENU_EXIT:
              gSpecialVar_Result = DAYCARE_EXITED_LEVEL_MENU;
              break;
          }
          DestroyListMenuTask(gTasks[taskId].tMenuListTaskId, NULL, NULL);
          ClearStdWindowAndFrame(gTasks[taskId].tWindowId, TRUE);
          RemoveWindow(gTasks[taskId].tWindowId);
          DestroyTask(taskId);
          ScriptContext_Enable();
      }
      else if (JOY_NEW(B_BUTTON))
      {
          gSpecialVar_Result = DAYCARE_EXITED_LEVEL_MENU;
          DestroyListMenuTask(gTasks[taskId].tMenuListTaskId, NULL, NULL);
          ClearStdWindowAndFrame(gTasks[taskId].tWindowId, TRUE);
          RemoveWindow(gTasks[taskId].tWindowId);
          DestroyTask(taskId);
          ScriptContext_Enable();
      }
}

